mapper.select:
SELECT , r.diagnosis FROM image_order o LEFT JOIN pet p ON o.pet_id = p.pet_id LEFT JOIN client c ON o.client_id = c.client_id LEFT JOIN doctor d ON o.doctor_id = d.doctor_id LEFT JOIN medical_record r ON o.record_id = r.record_id WHERE o.is_del = 0 AND o.is_cancel = 0
AND o.status = #{status}
ORDER BY o.status ASC, o.create_time DESC
